async function oldShop(selectedId=''){const selected=track(selectedId),products=(session?.products||[]).filter(p=>!selected||p.courseIds.includes(selected.id));const orders=mode==='connected'?(await legacyAPI('orders')).items:[];return heading('Access, payments and receipts.','Choose a pathway, confirm its terms, and pay securely. Your receipt appears after payment is confirmed.')+journey('access')+(selected?`<div class="notice path-selected"><b>Selected: ${esc(selected.title)}</b><a class="text-link" href="#path/${selected.id}">Review the pathway</a>${allowed(selected)?link('Continue learning','path/'+selected.id,true):''}</div>`:'')+`<div class="section-title"><h2>1. Choose your access</h2></div>${products.length?`<div class="course-grid">${products.map(p=>`<section class="panel"><h3>${esc(p.title)}</h3><p>${esc(window.AcademyReceipt.money(p.amount,p.currency))}</p><p class="small muted">Access for ${p.durationDays} days. Includes ${p.courseIds.map(id=>esc(track(id)?.title||id)).join(', ')}.</p><p class="small">${esc(p.refundPolicy)}</p><a href="${safeURL(p.termsUrl)}" target="_blank" rel="noopener">Purchase terms</a><label class="checkbox"><input type="checkbox" data-purchase-terms="${esc(p.id)}">I accept the purchase and refund terms.</label><button class="btn primary" data-action="checkout" data-id="${esc(p.id)}">Continue to secure checkout</button></section>`).join('')}</div>`:empty('Paid enrolment is not open yet.','No purchase or payment is simulated here. You can start the free foundation or explore the private practice preview.','Explore the free foundation','path/start')}<div class="panel"><div class="row between"><div><h2>2. Payment confirmation & your receipt</h2><p class="muted">Your receipt prints on screen after confirmed payment. The same order record remains available here.</p></div><a class="btn" href="#receipt/demo">Preview receipt animation</a></div><p class="small muted">The animation preview is clearly marked as a sample and makes no charge.</p></div><div class="section-title"><h2>Your orders & receipts</h2></div><div class="order-list">${orders.length?orders.map(o=>`<a class="journey-item" href="#receipt/${encodeURIComponent(o.id)}"><span class="sequence">${icon('Cart',16)}</span><div class="journey-content"><b>${esc(o.title||o.product_id)}</b><small>${new Date(o.created).toLocaleDateString()} · ${esc(window.AcademyReceipt.money(o.amount,o.currency))}</small></div><span class="status ${o.status==='Paid'?'good':''}">${esc(o.status)}</span>${icon('Arrow',16)}</a>`).join(''):'<div class="panel"><p class="muted">No orders yet. A sample animation never appears in your order history.</p></div>'}</div><div class="section-title"><h2>3. Your learning access</h2></div><div class="panel"><p class="muted">${mode==='preview'?'All '+atlas.tracks.length*10+' recipes are available in this private practice preview. No paid account or certificate is created.':'Your account access is checked before pathway lessons or submissions are accepted.'}</p><div class="table-scroll"><table><thead><tr><th>Pathway</th><th>Access</th><th>Next step</th></tr></thead><tbody>${atlas.tracks.map(t=>`<tr><td>${esc(t.title)}</td><td>${t.free?'Free foundation':mode==='preview'?'Practice preview':allowed(t)?'Active access':'Access required'}</td><td><a class="text-link" href="#${allowed(t)?'path/'+t.id:'shop/'+t.id}">${allowed(t)?'Open pathway':'View options'}</a></td></tr>`).join('')}</tbody></table></div></div><div class="notice">Free pathways do not require checkout. A receipt acknowledges payment; certificates require completed evidence, qualified review and independent verification.</div>`}
async function receiptPage(id){displayedReceipt=null;if(id==='demo'){const data={status:'Sample',activeCourseIds:[],receipt:{number:'SAMPLE',title:'Learning pathway',amount:0,currency:'aed',confirmedAt:null}};displayedReceipt={data,sample:true};return window.AcademyReceipt.render(data,true)}if(mode==='preview')return heading('No live order in this preview.','Practice mode does not create payments or receipts.')+link('Preview the receipt animation','receipt/demo',true)+link('Return to access','shop');if(!/^order-[a-f0-9]{40}$/.test(id||''))throw Error('This receipt link is incomplete. Open the order from Access & receipts.');
 const data=await legacyAPI('orders/'+encodeURIComponent(id));data.pathNames=Object.fromEntries(atlas.tracks.map(t=>[t.id,t.title]));
 if(data.receipt){session=await api('bootstrap');try{sessionStorage.removeItem('dba-pending-order');['stripe','gumroad','binance','crypto'].forEach(provider=>sessionStorage.removeItem('dba-checkout-key-'+data.product_id+'-'+provider))}catch{}displayedReceipt={data,sample:false};return window.AcademyReceipt.render(data)}
 const terminal=['Expired','Checkout failed','Refunded','Disputed'].includes(data.status);if(terminal){try{['stripe','gumroad','binance','crypto'].forEach(provider=>sessionStorage.removeItem('dba-checkout-key-'+data.product_id+'-'+provider));sessionStorage.removeItem('dba-pending-order')}catch{}}const cancelled=new URLSearchParams(location.search).get('checkout')==='cancelled';if(receiptOrder!==id){receiptOrder=id;receiptAttempts=0}if(!terminal&&!cancelled&&receiptAttempts<8){receiptAttempts++;receiptTimer=setTimeout(()=>{if(location.hash==='#receipt/'+id)render({quiet:true})},3000)}
 return heading(terminal?'This checkout did not complete.':cancelled?'You left checkout.':'Confirming your payment.',terminal?'No new receipt or learning access can be issued for this checkout.':cancelled?'An unpaid order does not grant learning access. We still check the actual order status.':'We are checking the payment record. Returning from checkout alone is not payment confirmation.')+`<ol class="checkout-steps" aria-label="Purchase progress"><li class="done"><span>1</span>Secure checkout</li><li class="current"><span>2</span>Confirm payment</li><li><span>3</span>Receipt & learning</li></ol><section class="panel receipt-wait"><span class="status">${esc(data.status)}</span><h2>${esc(data.title)}</h2><p>${esc(window.AcademyReceipt.money(data.amount,data.currency))}</p><p class="order-meta">Order ${esc(data.id)}</p><p class="muted">${terminal?'Return to access options if you would like to start a new checkout.':cancelled?'Use Check payment status if you completed payment in another tab.':'Your receipt animation will start once payment is confirmed. '+(receiptAttempts>=8?'Confirmation is taking longer. You can check again or return to this order later.':'Checking automatically…')}</p><div class="row"><button class="btn primary" data-action="refresh-receipt">Check payment status</button>${link('Access & receipts','shop')}</div></section>`}
